import type { MetadataRoute } from 'next';

/**
 * Web App Manifest (course ch.1 / ch.3 / workshop part B), generated by Next.js at
 * /manifest.webmanifest and linked automatically in <head>. Makes MoveUp installable.
 * display "standalone": own window without browser UI but WITH the OS status bar
 * (vs "fullscreen", which hides the status bar too — meant for games / video).
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: 'MoveUp — Moves, tracked to the millimetre',
    short_name: 'MoveUp',
    description:
      'Request a move, follow it, rate your mover and get help from the MoveUp assistant.',
    id: '/dashboard',
    start_url: '/dashboard',
    scope: '/',
    display: 'standalone',
    orientation: 'portrait',
    background_color: '#f2f1ec',
    theme_color: '#101010',
    categories: ['business', 'productivity', 'utilities'],
    icons: [
      { src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png' },
      { src: '/icons/icon-512.png', sizes: '512x512', type: 'image/png' },
      { src: '/icons/maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
    shortcuts: [
      {
        name: 'Open a claim',
        url: '/dashboard/claims/new',
        icons: [{ src: '/icons/icon-192.png', sizes: '192x192' }],
      },
      {
        name: 'Ask the assistant',
        url: '/dashboard/assistant',
        icons: [{ src: '/icons/icon-192.png', sizes: '192x192' }],
      },
    ],
  };
}
